update sys_import_log
batch_no = #{batchNo}, file_name = #{fileName}, file_size = #{fileSize}, file_type = #{fileType}, import_type = #{importType}, status = #{status}, total_rows = #{totalRows}, success_rows = #{successRows}, failed_rows = #{failedRows}, warning_rows = #{warningRows}, skipped_rows = #{skippedRows}, start_time = #{startTime}, end_time = #{endTime}, processing_time = #{processingTime}, error_message = #{errorMessage}, error_code = #{errorCode}, error_details = #{errorDetails}, validation_result = #{validationResult}, import_config = #{importConfig}, user_id = #{userId}, user_name = #{userName}, client_ip = #{clientIp}, user_agent = #{userAgent}, remarks = #{remarks}, del_flag = #{delFlag}, update_by = #{updateBy}, update_time = #{updateTime},
where log_id = #{logId}

