select count(*) as total_imports, sum(case when status = 'SUCCESS' then 1 else 0 end) as success_count, sum(case when status = 'FAILED' then 1 else 0 end) as failed_count, sum(case when status = 'PARTIAL_SUCCESS' then 1 else 0 end) as partial_success_count, sum(case when status = 'PROCESSING' then 1 else 0 end) as processing_count, sum(total_rows) as total_rows_processed, sum(success_rows) as total_success_rows, sum(failed_rows) as total_failed_rows, avg(processing_time) as avg_processing_time, max(processing_time) as max_processing_time, min(processing_time) as min_processing_time from sys_import_log where del_flag = '0'
and date_format(create_time,'%Y-%m-%d') >= #{startDate}
and date_format(create_time,'%Y-%m-%d') <= #{endDate}


where user_id = #{userId} and del_flag = '0'
order by create_time desc

    limit #{limit}

select error_code, count(*) as error_count from sys_import_log where del_flag = '0' and status = 'FAILED' and error_code is not null
and date_format(create_time,'%Y-%m-%d') >= #{startDate}
and date_format(create_time,'%Y-%m-%d') <= #{endDate}
group by error_code order by error_count desc

select import_type, count(*) as import_count, avg(processing_time) as avg_processing_time, avg(total_rows) as avg_total_rows, avg(file_size) as avg_file_size, sum(case when status = 'SUCCESS' then 1 else 0 end) / count(*) * 100 as success_rate from sys_import_log where del_flag = '0' and processing_time is not null
and date_format(create_time,'%Y-%m-%d') >= #{startDate}
and date_format(create_time,'%Y-%m-%d') <= #{endDate}
group by import_type order by import_count desc
